package com.chatsystem.admin.ui.cell;
import com.chatsystem.shared.model.UserAccount;import javafx.scene.control.*;import javafx.scene.layout.*;import java.util.function.LongConsumer;
public final class AdminUserCell extends ListCell<UserAccount>{private final LongConsumer open;public AdminUserCell(LongConsumer open){this.open=open;}@Override protected void updateItem(UserAccount u,boolean empty){super.updateItem(u,empty);if(empty||u==null){setGraphic(null);return;}Label text=new Label(u.getDisplayName()+"   "+u.getEmail()+"   "+u.getStatus());Button button=new Button("View details");button.getStyleClass().add("small-button");button.setOnAction(e->open.accept(u.getId()));HBox row=new HBox(16,text,button);row.getStyleClass().add("list-row");setGraphic(row);}}
